// Le site envoie { reference, creneaux: ["Lun_midi", ...] } : les créneaux à remplacer.
const body = $input.first().json.body || {};
const reference = String(body.reference || '').trim();
const creneaux = Array.isArray(body.creneaux) ? body.creneaux.map(String) : [];
return [{ json: { reference: reference, creneaux: creneaux } }];

// ---- Shared: turn Spoonacular results into our recipe pool (quantities scaled, nutrition per person) ----
function construirePool(recettes, personnes) {
  return recettes.map(function (r) {
    const facteur = personnes / (Number(r.servings) || personnes);
    const nutr = ((r.nutrition || {}).nutrients || []);
    const val = function (nom) { const n = nutr.find(function (x) { return x.name === nom; }); return n ? Math.round(n.amount) : null; };
    const outils = [];
    (r.analyzedInstructions || []).forEach(function (a) { (a.steps || []).forEach(function (s) { (s.equipment || []).forEach(function (e) { outils.push(String(e.name || '').toLowerCase()); }); }); });
    return {
      id: r.id, titre: r.title, temps_min: r.readyInMinutes,
      lien: r.sourceUrl || ('https://spoonacular.com/recipes/' + r.id),
      calories: val('Calories'), proteines: val('Protein'), outils: outils,
      ingredients: (r.extendedIngredients || []).map(function (i) {
        const m = (i.measures && i.measures.metric) ? i.measures.metric : null;
        return { nom: i.nameClean || i.name, quantite: Math.round((Number(m ? m.amount : i.amount) || 0) * facteur * 100) / 100, unite: m ? (m.unitShort || m.unitLong || '') : (i.unit || '') };
      })
    };
  });
}

// ---- Shared: equipment filter + "use up my fridge" ranking ----
function affinerPool(pool, o, besoin) {
  let p = pool;
  const FOUR = /oven|baking sheet|baking pan|baking dish|roasting|casserole dish|muffin|loaf pan/;
  const PLAQUE = /frying pan|skillet|pot|saucepan|wok|stove|grill pan|dutch oven/;
  const filtre = p.filter(function (r) {
    return !r.outils.some(function (x) { return (o.sansFour && FOUR.test(x)) || (o.sansPlaque && PLAQUE.test(x)); });
  });
  if (filtre.length >= Math.max(besoin, 3)) p = filtre; // keep enough candidates, the prompt still forbids the rest
  const stock = String(o.stock || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(Boolean);
  p = p.map(function (r) {
    const noms = r.ingredients.map(function (i) { return String(i.nom).toLowerCase(); });
    const utilise = stock.filter(function (s) { return noms.some(function (n) { return n.indexOf(s) !== -1 || s.indexOf(n) !== -1; }); });
    return Object.assign({}, r, { utilise: utilise });
  });
  if (o.frigo) p.sort(function (a, b) { return b.utilise.length - a.utilise.length; });
  return p.slice(0, 30);
}

// ---- Shared: leftovers logic ----
const JOURS_ORDRE = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
function diner_veille(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i > 0 ? JOURS_ORDRE[i - 1] + '_soir' : null; }
function dejeuner_lendemain(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i >= 0 && i < 6 ? JOURS_ORDRE[i + 1] + '_midi' : null; }
function estReste(c, restes, tous) { return !!restes && /_midi$/.test(c) && tous.indexOf(diner_veille(c)) !== -1; }
function nourritReste(c, restes, tous) { return !!restes && /_soir$/.test(c) && tous.indexOf(dejeuner_lendemain(c)) !== -1; }

// Decides what to replace. In leftovers mode, swapping a dinner also refreshes the
// next day's leftover lunch; a leftover lunch alone is rebuilt from its (kept) dinner.
const demande = $('Find Request').first().json || {};
const demandeSite = $('Read Swap').first().json;
const lignes = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.Creneau; });

if (!demande.Reference) return [{ json: { ok: false, message: 'No request matches this reference' } }];

let brut = {}; try { brut = JSON.parse(demande['Payload brut'] || '{}'); } catch (e) {}
const restes = !!brut.leftovers;
const tous = String(demande.Creneaux || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
let aRemplir = demandeSite.creneaux.filter(function (c) { return tous.indexOf(c) !== -1; });
aRemplir.slice().forEach(function (c) {
  if (nourritReste(c, restes, tous)) { const l = dejeuner_lendemain(c); if (aRemplir.indexOf(l) === -1) aRemplir.push(l); }
});
if (aRemplir.length === 0) return [{ json: { ok: false, message: 'No meal selected to replace' } }];

const actives = lignes.filter(function (r) { return r.Statut !== 'refuse'; });
const parCreneau = {}; actives.forEach(function (r) { parCreneau[r.Creneau] = r; });
const idsRefus = actives.filter(function (r) { return aRemplir.indexOf(r.Creneau) !== -1; }).map(function (r) { return r.id; });
const gardes = actives.filter(function (r) { return aRemplir.indexOf(r.Creneau) === -1; }).map(function (r) { return r.Plat; });
const dejaVus = lignes.map(function (r) { return Number(r['Spoonacular ID']); }).filter(Boolean);
const run = lignes.reduce(function (m, r) { return Math.max(m, Number(r.Run) || 1); }, 1) + 1;

const dinersGardes = {};
aRemplir.filter(function (c) { return estReste(c, restes, tous); }).forEach(function (c) {
  const d = diner_veille(c);
  if (aRemplir.indexOf(d) === -1 && parCreneau[d]) {
    const r = parCreneau[d];
    dinersGardes[d] = { id: Number(r['Spoonacular ID']), titre: r.Plat, lien: r['Lien recette'] || '', calories: r.Calories || 0, proteines: r.Proteines || 0 };
  }
});

let cuisines = demande.Cuisines || [];
if (!Array.isArray(cuisines)) cuisines = String(cuisines).split(',').map(function (s) { return s.trim(); }).filter(Boolean);

return [{ json: {
  ok: true, recordId: demande.id, reference: demande.Reference, budget: demande.Budget,
  personnes: Number(demande.Personnes) || 1, regime: demande.Regime || 'aucun', cuisines: cuisines,
  stock: demande.Stock || '', payloadBrut: demande['Payload brut'] || '',
  restes: restes, creneauxDemande: tous, creneaux: aRemplir, idsRefus: idsRefus,
  gardes: gardes, dejaVus: dejaVus, dinersGardes: dinersGardes, run: run
} }];

// One item per meal to mark as refused. Empty slots have nothing to mark:
// we still return one item so the workflow keeps going.
const ctx = $('Plan Swap').first().json;
if (ctx.idsRefus.length === 0) return [{ json: { rien: true } }];
return ctx.idsRefus.map(function (id) { return { json: { id: id } }; });

// ---- Shared: extra preferences stored in "Payload brut" (no new Airtable columns needed) ----
function lirePreferences(payloadBrut) {
  let b = {};
  try { b = JSON.parse(payloadBrut || '{}'); } catch (e) { b = {}; }
  const liste = function (x) { return Array.isArray(x) ? x.map(function (s) { return String(s).trim(); }).filter(Boolean) : []; };

  const CUISINES_SPOON = {
    'african':'African','africain':'African','american':'American','américain':'American','americain':'American',
    'british':'British','anglais':'British','cajun':'Cajun','caribbean':'Caribbean','caribéen':'Caribbean','antillais':'Caribbean',
    'chinese':'Chinese','chinois':'Chinese','eastern european':'Eastern European','european':'European','européen':'European',
    'french':'French','français':'French','german':'German','allemand':'German','greek':'Greek','grec':'Greek',
    'indian':'Indian','indien':'Indian','irish':'Irish','irlandais':'Irish','italian':'Italian','italien':'Italian',
    'japanese':'Japanese','japonais':'Japanese','jewish':'Jewish','korean':'Korean','coréen':'Korean','coreen':'Korean',
    'latin american':'Latin American','mediterranean':'Mediterranean','méditerranéen':'Mediterranean','mediterraneen':'Mediterranean',
    'mexican':'Mexican','mexicain':'Mexican','middle eastern':'Middle Eastern','nordic':'Nordic','scandinave':'Nordic',
    'southern':'Southern','spanish':'Spanish','espagnol':'Spanish','thai':'Thai','thaï':'Thai',
    'vietnamese':'Vietnamese','vietnamien':'Vietnamese','asian':'Asian','asiatique':'Asian'
  };
  const cuisinesSpoon = [], cuisinesLibres = [];
  liste(b.cuisines_extra).forEach(function (c) {
    const k = CUISINES_SPOON[c.toLowerCase()];
    if (k) cuisinesSpoon.push(k); else cuisinesLibres.push(c);
  });

  const INTOL = ['dairy','egg','gluten','grain','peanut','seafood','sesame','shellfish','soy','sulfite','tree nut','wheat'];
  const allergies = liste(b.allergies).filter(function (a) { return INTOL.indexOf(a) !== -1; });
  const allergiesAutres = liste(b.allergies_extra);
  const eviter = liste(b.exclude);
  const tempsMax = Number(b.max_time) || 0;
  const restes = !!b.leftovers;
  const lang = b.lang === 'fr' ? 'fr' : 'en';
  const nutrition = b.nutrition || 'balanced';
  const niveau = b.level || 'comfortable';
  const equipement = Array.isArray(b.equipment) ? b.equipment : ['oven', 'hob'];
  const sansFour = equipement.indexOf('oven') === -1 && equipement.indexOf('air_fryer') === -1;
  const sansPlaque = equipement.indexOf('hob') === -1;
  const lunchbox = !!b.lunchbox;
  const sansViande = Math.max(0, Math.min(7, Number(b.meat_free) || 0));
  const frigo = !!b.fridge_first;

  const params = [].concat(
    allergies.length ? ['intolerances=' + encodeURIComponent(allergies.join(','))] : [],
    (eviter.length || allergiesAutres.length) ? ['excludeIngredients=' + encodeURIComponent(eviter.concat(allergiesAutres).join(','))] : [],
    tempsMax ? ['maxReadyTime=' + tempsMax] : [],
    nutrition === 'protein' ? ['minProtein=25'] : [],
    nutrition === 'light' ? ['maxCalories=550'] : [],
    (sansFour || sansPlaque) ? ['addRecipeInstructions=true'] : []
  );

  const outils = { oven: 'an oven', hob: 'a hob', microwave: 'a microwave', air_fryer: 'an air fryer', blender: 'a blender',
    food_processor: 'a food processor', slow_cooker: 'a slow cooker', pressure_cooker: 'a pressure cooker', rice_cooker: 'a rice cooker', grill: 'a grill or barbecue' };
  const equipAutres = liste(b.equipment_extra);
  const lignes = [].concat(
    (allergies.length || allergiesAutres.length) ? ['- ALLERGIES, never include: ' + allergies.concat(allergiesAutres).join(', ')] : [],
    eviter.length ? ['- Foods the user does not eat: ' + eviter.join(', ')] : [],
    tempsMax ? ['- Maximum cooking time: ' + tempsMax + ' minutes'] : [],
    cuisinesLibres.length ? ['- Also enjoys these cuisines: ' + cuisinesLibres.join(', ')] : [],
    nutrition === 'protein' ? ['- Nutrition focus: high protein, favour recipes with the most protein.'] : [],
    nutrition === 'light' ? ['- Nutrition focus: lighter meals, favour lower-calorie recipes.'] : [],
    niveau === 'beginner' ? ['- The cook is a BEGINNER: pick simple recipes with few ingredients and basic techniques, nothing technical.'] : [],
    niveau === 'confident' ? ['- The cook is confident: more elaborate recipes are welcome.'] : [],
    ['- Kitchen equipment available: ' + (equipement.map(function (e) { return outils[e]; }).filter(Boolean).concat(equipAutres).join(', ') || 'very basic') + ', plus basic tools (knives, bowls). Never pick a recipe that needs equipment not in this list.'],
    equipement.some(function (e) { return ['slow_cooker', 'pressure_cooker', 'rice_cooker'].indexOf(e) !== -1; }) ? ['- Recipes that make good use of their slow cooker, pressure cooker or rice cooker are a plus.'] : [],
    equipement.indexOf('air_fryer') !== -1 ? ['- Air fryer available: air-fryer friendly recipes are a plus.'] : [],
    lunchbox ? ['- Lunches are eaten away from home: lunch dishes must travel well in a lunch box and taste good cold or reheated in a microwave.'] : [],
    sansViande ? ['- Make ' + sansViande + ' day(s) of the week fully meat-free (no meat, no fish), spread across the week.'] : [],
    frigo ? ['- USE UP THE PANTRY: build the week around the pantry ingredients, the recipes using the most of them come first.'] : [],
    lang === 'fr' ? ['- Language: write every titre (the dish name, translated naturally) and every pourquoi in French.'] : []
  );

  return {
    cuisinesSpoon: cuisinesSpoon, restes: restes, lang: lang, frigo: frigo, sansFour: sansFour, sansPlaque: sansPlaque,
    params: params, lignesPrompt: lignes
  };
}

