function estReste(c, restes, tous) { return !!restes && /_midi$/.test(c) && tous.indexOf(diner_veille(c)) !== -1; }
function nourritReste(c, restes, tous) { return !!restes && /_soir$/.test(c) && tous.indexOf(dejeuner_lendemain(c)) !== -1; }

// Builds the compact prompt for the cooking slots only (leftover lunches are copied later).
function construirePrompt(o) {
  const cuisson = o.aRemplir.filter(function (c) { return !estReste(c, o.restes, o.creneauxDemande); });
  const doubles = cuisson.filter(function (c) { return nourritReste(c, o.restes, o.creneauxDemande); });
  const lignes = o.pool.map(function (r) {
    return r.id + ' | ' + r.titre + ' | ' + r.temps_min + ' min | ' + (r.proteines ? r.proteines + ' g protein | ' : '') +
      r.ingredients.map(function (i) { return i.nom; }).join(', ') + (o.frigo && r.utilise && r.utilise.length ? ' | uses pantry: ' + r.utilise.join(', ') : '');
  });
  const ex = { creneau: cuisson[0] || 'Lun_soir', recette_id: o.pool[0].id };
  if (o.lang === 'fr') ex.titre = 'Nom du plat en français';
  ex.pourquoi = o.lang === 'fr' ? 'Une phrase courte.' : 'One short sentence.';
  ex.cout_estime = 6.5;
  const prompt = [o.intro,
    "- Budget for the whole week: " + o.budget + " euros for " + o.personnes + " people",
    "- Diet: " + o.regime,
    o.notes ? "- Also take into account: " + o.notes : "",
