    JSON.stringify({ repas: [ex] })
  ]).filter(Boolean).join('\n');
  return {
    cuisson: cuisson,
    corpsLLM: {
      model: 'openai/gpt-oss-120b', max_tokens: 6000, reasoning_effort: 'low', temperature: 0.4,
      response_format: { type: 'json_object' },
      messages: [
