  intro: "The user rejected some meals of their weekly plan. Pick replacements. Answer ONLY with a JSON object.",
  aRemplir: ctx.creneaux, creneauxDemande: ctx.creneauxDemande, restes: ctx.restes, lang: req.lang, frigo: req.frigo,
  pool: pool.length ? pool : [{ id: 0, titre: '', temps_min: 0, ingredients: [] }],
  budget: ctx.budget, personnes: ctx.personnes, regime: ctx.regime, stock: ctx.stock,
  lignesPrefs: req.lignesPrefs, gardes: ctx.gardes
});
return [{ json: {
  echec: false, recordId: ctx.recordId, reference: ctx.reference, run: ctx.run, lang: req.lang,
  creneauxDemande: ctx.creneauxDemande, aRemplir: ctx.creneaux, cuisson: p.cuisson,
  restes: ctx.restes, dinersGardes: ctx.dinersGardes, pool: pool, corpsLLM: p.corpsLLM
} }];

