  });
  if (filtre.length >= Math.max(besoin, 3)) p = filtre; // keep enough candidates, the prompt still forbids the rest
  const stock = String(o.stock || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(Boolean);
  p = p.map(function (r) {
    const noms = r.ingredients.map(function (i) { return String(i.nom).toLowerCase(); });
    const utilise = stock.filter(function (s) { return noms.some(function (n) { return n.indexOf(s) !== -1 || s.indexOf(n) !== -1; }); });
    return Object.assign({}, r, { utilise: utilise });
  });
  if (o.frigo) p.sort(function (a, b) { return b.utilise.length - a.utilise.length; });
  return p.slice(0, 30);
}

// ---- Shared: leftovers logic ----
const JOURS_ORDRE = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
function diner_veille(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i > 0 ? JOURS_ORDRE[i - 1] + '_soir' : null; }
function dejeuner_lendemain(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i >= 0 && i < 6 ? JOURS_ORDRE[i + 1] + '_midi' : null; }
function estReste(c, restes, tous) { return !!restes && /_midi$/.test(c) && tous.indexOf(diner_veille(c)) !== -1; }
function nourritReste(c, restes, tous) { return !!restes && /_soir$/.test(c) && tous.indexOf(dejeuner_lendemain(c)) !== -1; }

// Parses the Groq answer, re-attaches recipe data, doubles dinners that feed
// tomorrow's lunch, and writes leftover lunches as copies of that dinner.
const rep = $input.first().json;
function echec(raison) { return [{ json: { echec: true, raison: raison, recordId: ctx.recordId } }]; }
if (rep.error) return echec('Groq : ' + (rep.error.message || JSON.stringify(rep.error)).slice(0, 200));

let proposes = [];
if (ctx.cuisson.length) {
  const choix = (rep.choices || [])[0];
  if (!choix || !choix.message) return echec("Groq n'a pas renvoyé de réponse");
  if (choix.finish_reason === 'length') return echec('Réponse tronquée (max_tokens)');
  try {
    const sortie = JSON.parse(String(choix.message.content || '').replace(/```json|```/g, '').trim());
    proposes = Array.isArray(sortie.repas) ? sortie.repas : [];
  } catch (e) { return echec('JSON invalide renvoyé par Groq'); }
}

const FR = ctx.lang === 'fr';
const JOURS = FR ? { Lun: 'lundi', Mar: 'mardi', Mer: 'mercredi', Jeu: 'jeudi', Ven: 'vendredi', Sam: 'samedi', Dim: 'dimanche' }
                 : { Lun: 'Monday', Mar: 'Tuesday', Mer: 'Wednesday', Jeu: 'Thursday', Ven: 'Friday', Sam: 'Saturday', Dim: 'Sunday' };
const TXT = FR
  ? { ajout: 'Ajouté pour compléter ta semaine.', double: ' Préparé en double pour le déjeuner du lendemain.', reste: function (j) { return 'Restes du dîner de ' + j + '.'; } }
  : { ajout: 'Added to complete your week.', double: " Cooked in double for tomorrow's lunch.", reste: function (j) { return 'Leftovers from ' + j + ' dinner.'; } };

const parId = {}; ctx.pool.forEach(function (r) { parId[String(r.id)] = r; });
const parCreneau = {}; proposes.forEach(function (m) { if (m && m.creneau) parCreneau[String(m.creneau).trim()] = m; });
const utilises = {};
const cuisines = {};

function ligne(creneau, src, titre, pourquoi, cout, ingredients, temps) {
  const parts = creneau.split('_');
  return {
    "Identifiant": ctx.reference + '_' + creneau, "Creneau": creneau, "Jour": parts[0] || '', "Moment": parts[1] || '',
    "Plat": titre || src.titre, "Spoonacular ID": src.id, "Lien recette": src.lien || '', "Pourquoi ce plat": pourquoi || '',
    "Ingredients": JSON.stringify(ingredients), "Cout estime": Math.round((Number(cout) || 0) * 100) / 100,
    "Calories": src.calories || 0, "Proteines": src.proteines || 0, "Temps": temps || 0,
    "Statut": "propose", "Run": ctx.run, "Demande": ctx.reference
  };
}

ctx.cuisson.forEach(function (creneau) {
  const m = parCreneau[creneau] || {};
  let src = parId[String(m.recette_id)];
  let pourquoi = m.pourquoi, titre = FR ? m.titre : null;
  if (!src || utilises[src.id]) {
    src = ctx.pool.find(function (r) { return !utilises[r.id]; });
    // Pool exhausted: better an empty slot the user can fill than the same dish twice.
    if (!src) return;
    pourquoi = TXT.ajout; titre = null;
  }
  utilises[src.id] = true;
  const double = nourritReste(creneau, ctx.restes, ctx.creneauxDemande);
  const f = double ? 2 : 1;
  const ing = (src.ingredients || []).map(function (i) { return { nom: i.nom, quantite: Math.round(i.quantite * f * 100) / 100, unite: i.unite }; });
  cuisines[creneau] = ligne(creneau, src, titre, double ? (pourquoi || '') + TXT.double : pourquoi, (Number(m.cout_estime) || 0) * f, ing, src.temps_min);
});

const restesLignes = [];
ctx.aRemplir.filter(function (c) { return estReste(c, ctx.restes, ctx.creneauxDemande); }).forEach(function (c) {
  const d = diner_veille(c);
  const n = cuisines[d];
  const src = n ? { id: n["Spoonacular ID"], titre: n.Plat, lien: n["Lien recette"], calories: n.Calories, proteines: n.Proteines } : ctx.dinersGardes[d];
  if (!src) return;
  restesLignes.push(ligne(c, src, null, TXT.reste(JOURS[d.split('_')[0]]), 0, [], 0));
});

const tout = Object.keys(cuisines).map(function (k) { return cuisines[k]; }).concat(restesLignes);
if (tout.length === 0) return echec('Aucun repas proposé');
return tout.map(function (j) { return { json: j }; });
